def test_html_to_pdf_and_save_locally(html_content):
    output_pdf_path = os.path.join(OUTPUT_DIR, "test_output.pdf")

    html_to_pdf(html_content, output_pdf_path, PDFOptions())

    assert os.path.exists(output_pdf_path), "PDF file was not created."
    assert os.path.getsize(output_pdf_path) > 0, "PDF file is empty."
